using System;
using System.Collections.Generic;
using Codrio.Rendering;

namespace Codrio;

/// <summary>Builds a C# source file containing headers, using directives, and declarations.</summary>
/// <remarks>Builders are mutable and are not thread-safe.</remarks>
public sealed class FileBuilder
{
    internal bool autoGeneratedHeader;
    internal bool nullableEnable;
    internal readonly List<string> usings = new();
    internal readonly List<Action<CodeWriter>> items = new();

    internal FileBuilder()
    {
    }

    /// <summary>Includes the auto-generated header once, before the nullable directive.</summary>
    /// <returns>This file builder.</returns>
    public FileBuilder AutoGeneratedHeader()
    {
        autoGeneratedHeader = true;
        return this;
    }

    /// <summary>Includes the nullable enable directive once.</summary>
    /// <returns>This file builder.</returns>
    public FileBuilder NullableEnable()
    {
        nullableEnable = true;
        return this;
    }

    /// <summary>Adds a using directive without validating or deduplicating its name.</summary>
    /// <param name="name">The text to place between the using keyword and semicolon.</param>
    /// <returns>This file builder.</returns>
    /// <exception cref="ArgumentNullException"><paramref name="name"/> is null.</exception>
    public FileBuilder Using(string name)
    {
        if (name is null)
        {
            throw new ArgumentNullException(nameof(name));
        }

        usings.Add(name);
        return this;
    }

    /// <summary>Adds an empty block namespace declaration.</summary>
    /// <param name="name">The namespace name, written without validation.</param>
    /// <returns>This file builder.</returns>
    /// <exception cref="ArgumentNullException"><paramref name="name"/> is null.</exception>
    public FileBuilder Namespace(string name) => Add(CSharp.Namespace(name));

    /// <summary>Immediately configures a new namespace builder and adds it to the file.</summary>
    /// <param name="name">The namespace name, written without validation.</param>
    /// <param name="configure">The action to run on the new builder.</param>
    /// <returns>This file builder.</returns>
    /// <exception cref="ArgumentNullException"><paramref name="name"/> or <paramref name="configure"/> is null.</exception>
    public FileBuilder Namespace(string name, Action<NamespaceBuilder> configure) => Add(CSharp.Namespace(name, configure));

    /// <summary>Adds the supplied namespace builder by reference without copying it.</summary>
    /// <param name="namespaceBuilder">The namespace builder to add.</param>
    /// <returns>This file builder.</returns>
    /// <exception cref="ArgumentNullException"><paramref name="namespaceBuilder"/> is null.</exception>
    public FileBuilder Add(NamespaceBuilder namespaceBuilder)
    {
        if (namespaceBuilder is null)
        {
            throw new ArgumentNullException(nameof(namespaceBuilder));
        }

        items.Add(namespaceBuilder.Write);
        return this;
    }

    /// <summary>Adds an empty top-level class declaration.</summary>
    /// <param name="name">The class identifier. Reserved keywords are escaped.</param>
    /// <returns>This file builder.</returns>
    /// <exception cref="ArgumentNullException"><paramref name="name"/> is null.</exception>
    /// <exception cref="ArgumentException"><paramref name="name"/> is not a valid C# identifier.</exception>
    public FileBuilder Class(string name) => Add(CSharp.Class(name));

    /// <summary>Immediately configures a new class builder and adds it as a top-level declaration.</summary>
    /// <param name="name">The class identifier. Reserved keywords are escaped.</param>
    /// <param name="configure">The action to run on the new builder.</param>
    /// <returns>This file builder.</returns>
    /// <exception cref="ArgumentNullException"><paramref name="name"/> or <paramref name="configure"/> is null.</exception>
    /// <exception cref="ArgumentException"><paramref name="name"/> is not a valid C# identifier.</exception>
    public FileBuilder Class(string name, Action<ClassBuilder> configure) => Add(CSharp.Class(name, configure));

    /// <summary>Adds the supplied class builder by reference without copying it.</summary>
    /// <param name="classBuilder">The class builder to add.</param>
    /// <returns>This file builder.</returns>
    /// <exception cref="ArgumentNullException"><paramref name="classBuilder"/> is null.</exception>
    public FileBuilder Add(ClassBuilder classBuilder)
    {
        if (classBuilder is null)
        {
            throw new ArgumentNullException(nameof(classBuilder));
        }

        items.Add(classBuilder.Write);
        return this;
    }

    /// <summary>Adds unvalidated source text, normalizing CRLF line endings to LF.</summary>
    /// <param name="code">The source text to write as one or more lines.</param>
    /// <returns>This file builder.</returns>
    /// <exception cref="ArgumentNullException"><paramref name="code"/> is null.</exception>
    public FileBuilder Raw(string code)
    {
        if (code is null)
        {
            throw new ArgumentNullException(nameof(code));
        }

        items.Add(writer => writer.WriteLine(code));
        return this;
    }

    internal void Write(CodeWriter writer)
    {
        if (autoGeneratedHeader)
        {
            writer.WriteLine("// <auto-generated/>");
        }

        if (nullableEnable)
        {
            writer.WriteLine("#nullable enable");
        }

        var hasHeader = autoGeneratedHeader || nullableEnable;
        if (hasHeader && usings.Count > 0)
        {
            writer.WriteBlankLine();
        }

        foreach (var name in usings)
        {
            writer.WriteLine("using " + name + ";");
        }

        if ((hasHeader || usings.Count > 0) && items.Count > 0)
        {
            writer.WriteBlankLine();
        }

        for (var i = 0; i < items.Count; i++)
        {
            if (i > 0)
            {
                writer.WriteBlankLine();
            }

            items[i](writer);
        }
    }

    /// <summary>Renders the source file with one blank line between sections and items.</summary>
    /// <returns>The source with LF line endings, or an empty string when the builder is empty.</returns>
    public override string ToString()
    {
        var writer = new CodeWriter();
        Write(writer);
        return writer.ToString();
    }
}
